"""Retry policy for outbound HTTP calls made through shipclient."""

import re
from datetime import datetime, timezone

_RETRYABLE_STATUSES = {429, 502, 503, 504}
_IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_UNSAFE_METHODS = {"POST", "PATCH"}

_DEFAULT_PROFILE = (5, 8.0, 30.0)
_PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_MONTHS = {
    "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
    "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12,
}
_DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
_HTTP_DATE = re.compile(
    r"([A-Z][a-z]{2}), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) "
    r"(\d{2}):(\d{2}):(\d{2}) GMT"
)


def _header(headers, name):
    for key, value in (headers or {}).items():
        if key.lower() == name:
            return value
    return None


def _parse_retry_after(value, now):
    if value is None:
        return None
    text = value.strip()
    if re.fullmatch(r"[0-9]+", text):
        return float(int(text))
    match = _HTTP_DATE.fullmatch(text)
    if not match:
        return None
    day_name, day, month, year, hour, minute, second = match.groups()
    if day_name not in _DAYS or month not in _MONTHS:
        return None
    try:
        moment = datetime(
            int(year), _MONTHS[month], int(day),
            int(hour), int(minute), int(second), tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    if _DAYS[moment.weekday()] != day_name:
        return None
    return max(0.0, (moment - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    if status is not None and status not in _RETRYABLE_STATUSES:
        return None

    verb = method.upper()
    if verb in _UNSAFE_METHODS:
        key = _header(request_headers, "idempotency-key")
        if key is None or not key.strip():
            return None
    elif verb not in _IDEMPOTENT_METHODS:
        return None

    service = _header(request_headers, "x-service")
    profile = _DEFAULT_PROFILE
    if service is not None:
        profile = _PROFILES.get(service.strip().lower(), _DEFAULT_PROFILE)
    max_attempts, cap, max_retry_after = profile

    if attempt >= max_attempts:
        return None

    delay = min(cap, 0.25 * 2 ** (attempt - 1))

    if status in (429, 503):
        wait = _parse_retry_after(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(delay, wait)
    return delay
EOF
